import { createClient } from '@supabase/supabase-js';
import { auth } from '@clerk/nextjs/server';

/**
 * Server-side Supabase client.
 * Carries the Clerk JWT with every request so RLS policies can evaluate auth.uid() and custom claims.
 * Sessions belong to Clerk; Supabase session persistence and refresh are disabled.
 */
export async function createServerSupabaseClient() {
  const { getToken } = await auth();
  
  // Retrieve the JWT generated by Clerk (e.g. using the supabase template or default session token)
  let token: string | null = null;
  try {
    token = await getToken({ template: 'supabase' });
  } catch {
    try {
      token = await getToken();
    } catch {
      token = null;
    }
  }

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://placeholder.supabase.co';
  const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'placeholder-anon-key';

  return createClient(supabaseUrl, supabaseAnonKey, {
    global: {
      headers: token ? { Authorization: `Bearer ${token}` } : {},
    },
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
  });
}
